SELECT D.ID, D.PRATICA_ID, D.DIA, D.HUMOR, D.SENTIU, P.TIPO, P.JEITO, P.TITULO, P.SEGUNDO, V.YT_VIDEO_ID, C.NOME CANAL FROM PRATICA_DIARIO D JOIN PRATICAS P ON P.ID = D.PRATICA_ID JOIN VIDEOS V ON V.ID = P.VIDEO_ID JOIN CANAIS C ON C.ID = V.CANAL_ID WHERE ({{praticaId}} = 0 OR D.PRATICA_ID = {{praticaId}}) ORDER BY D.DIA DESC, D.ID DESC LIMIT {{limit}} OFFSET {{offset}}